def solve_knights_tour(n, start):
    def get_moves(r, c):
        moves = []
        for dr, dc in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                moves.append(nr * n + nc)
        return moves

    adj = {i: get_moves(i // n, i % n) for i in range(n * n)}

    path = [start]
    visited = set([start])

    def dfs(curr):
        if len(path) == n * n:
            return True

        # Warnsdorff's heuristic: sort by number of onward moves
        next_moves = []
        for nxt in adj[curr]:
            if nxt not in visited:
                count = sum(1 for nnxt in adj[nxt] if nnxt not in visited)
                next_moves.append((count, nxt))

        next_moves.sort()

        for _, nxt in next_moves:
            visited.add(nxt)
            path.append(nxt)
            if dfs(nxt):
                return True
            path.pop()
            visited.remove(nxt)

        return False

    if dfs(start):
        return path
    return None

path = solve_knights_tour(7, 0)
print(path)
